import { Injectable } from "@angular/core";
import { HttpClient, HttpParams } from "@angular/common/http";
import { Observable } from "rxjs";
import { shareReplay } from "rxjs/operators";
import { House } from "../models/house.model";
import { environment } from "../../../environments/environment";

@Injectable({ providedIn: 'root' })
export class HouseService {

  apiUrl: string = environment.apiUrl;

  // Cache de la page 1 (évite une requête réseau à chaque retour sur la liste)
  private page1Cache$?: Observable<any>;

  constructor(private http: HttpClient) { }

  // 🔹 Récupération avec pagination
  getHouses(page: number = 1, limit: number = 15, sort: string = "createdAt"): Observable<any> {
    const params = new HttpParams()
      .set("page", page.toString())
      .set("limit", limit.toString())
      .set("sort", sort);

    // Cache uniquement pour la première page
    if (page === 1 && !this.page1Cache$) {
      this.page1Cache$ = this.http.get<any>(`${this.apiUrl}/houses`, { params }).pipe(shareReplay(1));
    }
    return page === 1 ? this.page1Cache$! : this.http.get<any>(`${this.apiUrl}/houses`, { params });
  }

  /** Invalide le cache (à appeler après une création/modification) */
  clearCache(): void {
    this.page1Cache$ = undefined;
  }

  // 🔹 Récupérer une maison par ID
  getHouseById(_id: string): Observable<House> {
    return this.http.get<House>(`${this.apiUrl}/houses/${_id}`);
  }

  // 🔹 Ajouter une maison
  addHouse(formData: FormData): Observable<House> {
    return this.http.post<House>(`${this.apiUrl}/houses`, formData);
  }

  // 🔹 Modifier une maison
  updateHouse(id: string, formData: FormData): Observable<House> {
    this.clearCache(); // invalider le cache après une modification
    return this.http.put<House>(`${this.apiUrl}/houses/${id}`, formData);
  }

  // 🔹 Recherche avec filtres + pagination
  searchHouses(filters: {

    place?: string;
    city?: string;
    type?: string;
    maxPrice?: number;
    page?: number;
    limit?: number;
    sort?: string;
  }): Observable<any> {

    let params = new HttpParams();

    if (filters.place) params = params.set("value", filters.place);
    if (filters.city) params = params.set("city", filters.city);
    if (filters.type) params = params.set("type", filters.type);
    if (filters.maxPrice) params = params.set("maxPrice", filters.maxPrice.toString());
    if (filters.page) params = params.set("page", filters.page.toString());
    if (filters.limit) params = params.set("limit", filters.limit.toString());
    if (filters.sort) params = params.set("sort", filters.sort);


    return this.http.get<any>(`${this.apiUrl}/houses/search`, { params });
  }
  // 🔹 Toggle House Status (Activate/Deactivate)
  toggleStatus(_id: string): Observable<House> {
    return this.http.patch<House>(`${this.apiUrl}/houses/${_id}/status`, {});
  }
}
